result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/test_laplace.py", "content": "import numpy as np
import pytest

from laplace import exact_solution, solve_laplace

CENTER_EXACT = np.sinh(np.pi / 2.0) / np.sinh(np.pi)  # T(0.5, 0.5)


@pytest.fixture(scope="module")
def sol129():
    return solve_laplace(129)


def _error(T, x):
    X, Y = np.meshgrid(x, x)
    return np.max(np.abs(T - exact_solution(X, Y)))


def test_residual_below_tolerance(sol129):
    assert sol129["residual"] < 1e-10


def test_max_norm_error_vs_analytic(sol129):
    err = _error(sol129["T"], sol129["x"])
    assert err < 5e-5, f"max-norm error {err:.3e} >= 5e-5"


def test_center_point_value(sol129):
    T = sol129["T"]
    center = T[T.shape[0] // 2, T.shape[1] // 2]
    assert abs(center - CENTER_EXACT) < 1e-4


def test_discrete_maximum_principle(sol129):
    T = sol129["T"]
    boundary = np.concatenate([
        T[0, :], T[-1, :], T[:, 0], T[:, -1]
    ])
    bmin, bmax = boundary.min(), boundary.max()
    interior = T[1:-1, 1:-1]
    assert interior.min() > bmin, "interior minimum touches/exceeds boundary min"
    assert interior.max() < bmax, "interior maximum touches/exceeds boundary max"


def test_second_order_convergence_65_to_129():
    e65 = _error(**{k: solve_laplace(65)[k] for k in ("T", "x")})
    e129 = _error(**{k: solve_laplace(129)[k] for k in ("T", "x")})
    ratio = e65 / e129
    print(f"\ne(65)={e65:.3e}  e(129)={e129:.3e}  ratio={ratio:.3f}")
    assert 3.5 <= ratio <= 4.5, f"convergence ratio {ratio:.3f} outside [3.5, 4.5]"
